import{_ as o,l,o as e,c as r,v as t,p as s,x as n,d as p,i as d,S as m}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"P-tuning v2","description":"","frontmatter":{"title":"P-tuning v2","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/p-tuning-v2.md","filePath":"llm/p-tuning-v2.md","lastUpdated":1789023840000}'),h={name:"llm/p-tuning-v2.md"};function u(c,a,A,T,E,P){const i=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=t('<h1 id="p-tuning-v2" tabindex="-1">P-tuning v2 <a class="header-anchor" href="#p-tuning-v2" aria-label="Permalink to &quot;P-tuning v2&quot;">​</a></h1><div class="epigraph"><p>可训练的不是任务描述句子，而是插在每一层的前缀键值；深度提示让提示调参在大模型与硬任务上追上全参微调的量级。</p><footer>—— Liu 等，P-Tuning v2: Prompt Tuning Can Be Comparable to Fine-tuning Universally Across Scales and Tasks，ACL 2022</footer></div><p><a href="/llm/bitfit">BitFit</a> 不改 \\(W\\)，只平移激活。提示调参也不改 \\(W\\)，但在序列前端（或每层）插入可学习的「虚 token」。Liu 等人的 P-Tuning v2 针对 v1 / Lester 式 Prompt Tuning 的失败：只在输入嵌入层加前缀，小模型或难任务上远弱于全参。v2 把前缀做到每一层的注意力，作为深度提示。缺口：与 <a href="/llm/lora">LoRA</a> 同属 PEFT，但侵入的是 KV 缓存与序列长度，不是矩阵加法。后课合并冲突默认你已能区分「适配器」与「前缀」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离散 prompt 要人工写；连续 prompt 把 \\(n\\) 个虚向量当参数，经嵌入层进入注意力。只插在第 0 层时，后续层看到的是被冻结 Transformer 变换过的提示，能调控的自由度随深度衰减。大模型上 Lester 等人曾显示仅输入前缀就够；中小模型与序列标注上不够。P-Tuning v2 要恢复深度上的控制：每层自己的前缀 KV，使注意力在每一层都能「看见」任务提示。</p><p>指令 LLM 还有<a href="/llm/chat-template">chat template</a>：真实特殊 token 与虚前缀并存。虚前缀不进词表、不进用户可见字符串，但占序列位置、进 KV。推理必须加载同一份前缀，否则条件 OOD——与模板不一致同构。</p><h3 id="前缀长度是序列税-不是参数税" tabindex="-1">前缀长度是序列税，不是参数税 <a class="header-anchor" href="#前缀长度是序列税-不是参数税" aria-label="Permalink to &quot;前缀长度是序列税，不是参数税&quot;">​</a></h3><p>\\(n\\) 个前缀 token 每层增加 \\(n\\) 的 KV。长上下文里这与<a href="/llm/long-context-finetune">长微调</a>抢预算。LoRA 合并后不占序列。任务极多时，前缀按任务存小，但 decode 每步都要带着任务 KV。这是服务差异，不是准确率差异。</p><p><span class="marginnote">原文覆盖 NLU 与序列标注，强调「跨尺度、跨任务可与微调相比」。生成式助手 SFT 上，实践更常选 LoRA；P-tuning 仍是合法 PEFT，尤其在不能改权重文件、只能加前缀缓存时。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每层注意力，拼接可学习前缀 \\(P_K,P_V\\)（长度 \\(n\\)）到真实序列的 K、V 上，再做 SDPA。参数量约 \\(L\\times n\\times d\\) 量级（或再经小 MLP 重参数化，v1 常用）。冻结原 \\(W\\)。初始化前缀为小随机，避免初期注意力全被前缀吸走。学习率偏适配器侧。SFT 时<a href="/llm/response-only-loss">仅回复损失</a>只在真实助手 token 上；前缀位置始终是条件，不计损失。</p><p>与对话模板：先渲染 messages，再在模型内部插前缀，不要把前缀写成用户可见的「系统提示替代」——除非你有意让二者合一。推理 <code>add_generation_prompt</code> 仍按模板；前缀作为额外 KV 加载。</p>',12)),(e(),s(m,null,{default:n(()=>[d(i,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22chat%20template%20%E7%9C%9F%E5%AE%9E%20token%22%5D%20--%3E%20ATT%5B%22%E6%AF%8F%E5%B1%82%E6%B3%A8%E6%84%8F%E5%8A%9B%22%5D%0A%20%20P%5B%22%E5%8F%AF%E5%AD%A6%E4%B9%A0%E5%89%8D%E7%BC%80%20KV%22%5D%20--%3E%20ATT%0A%20%20ATT%20--%3E%20Y%5B%22%E4%BB%85%E5%9B%9E%E5%A4%8D%E6%8D%9F%E5%A4%B1%E5%9C%A8%E7%9C%9F%E5%AE%9E%E5%8A%A9%E6%89%8B%E4%B8%8A%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>\\(n\\) 从 8–64 扫。过大则过拟合短指令，且税重。可与 LoRA 同用，但很难归因，默认二选一做主。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前缀 KV 提供与位置无关（或有独立位置编码）的任务记忆：查询真实 token 时可以读到这些键。深度前缀让每一层都能重新读任务，不依赖第 0 层把提示信息无损传下去。这比 BitFit 更能引入「新的可寻址记忆」，比 LoRA 更少改内容通道 \\(W\\)。失败时表现为：模型会说对任务口头禅，却改不好计算，因为 FFN 权重冻结。</p><p>多任务切换只换前缀 KV，基座唯一。前缀之间相加没有良好定义——应切换而不是平均，除非做了专门的组合训练。这点接到<a href="/llm/lora-merge-conflict">LoRA 合并</a>：前缀冲突同样存在，只是发生在 KV 里。</p><p><span class="marginnote">P-tuning 不替代系统提示。系统提示是离散、人写、进模板的；前缀是连续、训练出来的。混用时两者都是条件，调试要对齐加载。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>权重必须能在每层注入前缀接口；闭源 API 做不到 v2。生成长度很长时，前缀占的 KV 恒定，相对税下降，但首包延迟仍在。领域术语内化仍弱，应 <a href="/llm/domain-adaptation-ft">DAPT</a> 或 LoRA。v2 论文早于 ChatGPT 对话栈，迁移时把「CLS 头」换成 LM 头即可，不要复用分类超参当生成超参。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>P-Tuning v2 在每一层插入可学习前缀 KV，冻结 \\(W\\)。</li><li>深度提示补上「只在嵌入层加 prompt」的表达力缺口。</li><li>前缀占序列与 KV，服务税与 LoRA 不同。</li><li>损失不计前缀位置；须与 chat template 一起加载。</li><li>适合多任务切前缀、不能写权重时；生成 SFT 默认仍常选 LoRA。</li><li>出处：Liu 等，P-Tuning v2，ACL 2022。</li></ul>',9))])}const g=o(h,[["render",u]]);export{f as __pageData,g as default};
